import raw from './inventory-templates.json';
import type { InventoryTemplates } from './inventory.ts';

/** The quick-slot parts are absent from a templates file harvested before the quick slots were read. */
type Harvested = Omit<InventoryTemplates, 'quickDigits' | 'quickTails'> & Partial<Pick<InventoryTemplates, 'quickDigits' | 'quickTails'>>;

/** The shipped Use-tab and quick-slot templates: digits, remnants and item icons, generated by scripts/harvest-inventory.mjs. */
export const DEFAULT_INVENTORY_TEMPLATES: InventoryTemplates = { quickDigits: {}, quickTails: [], ...(raw as Harvested) };
